/*
 * NOVA_ATELIER — Filmstrip 3D Carousel (hub-visual-stage)
 * 1) COMPOSITION: dark gradient stage backdrop (z=-2.5) behind a 5-card filmstrip
 *    group rotated -18deg on Y for perspective recession; focused card (x=0)
 *    counter-rotates flat-to-camera at scale 1.0; headline/body pinned in world
 *    space; radial contact-shadow grounds the strip.
 * 2) LIGHT RIG: rig-dusk-editorial — ambient floor 0.09 + key directional
 *    (#ffc890 2.8) + fill point (#b9a68e 3, dist 9 decay 2) + rim directional
 *    (#f2f4f6 1.7), all node-local children of the returned group.
 * 3) MATERIALS: MeshPhysicalNodeMaterial per card (roughness .55, metalness .2,
 *    clearcoat .15) sharing the single provided photograph map, differentiated
 *    by neutral-gray tint multipliers (no new hues) to read as distinct plates;
 *    ink machined-bevel frame boxes; emissive accent underline bar.
 * 4) MOTION: weighted-settle entrance (power4 overshoot 1.04->1.0), slow
 *    breathing idle (<=2% scale, sine), parallax-scroll primitive drives strip
 *    translate-x + per-card UV counter-shift on scroll.
 * 5) FOCAL ELEMENT: the center, camera-facing focused card (NA-03 SIGNAL) with
 *    its red emissive underline bar — brightest, sharpest, only frontal plate.
 */

import {
  Group,
  Mesh,
  PlaneGeometry,
  BoxGeometry,
  DirectionalLight,
  PointLight,
  AmbientLight,
  Object3D,
  MeshBasicNodeMaterial,
  MeshPhysicalNodeMaterial,
  MeshStandardNodeMaterial,
} from 'three/webgpu';
import { uv, mix, color, vec2, length, smoothstep } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const root = new Group();
  root.name = 'filmstrip-carousel';

  const disposables = { geometries: [], materials: [], textures: [] };
  const timelines = [];
  const primitiveHandles = [];

  // ---- text bridging idiom ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline');
  const bodyItem = items.find((i) => i.role === 'body');
  const captionItems = items.filter((i) => i.role === 'caption');

  const PALETTE = {
    background: '#0b0b10',
    surface: '#14141a',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
  };

  // ---- color.background / color.surface / color.gradient : backdrop stage ----
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(color(PALETTE.background), color('#12121a'), uv().y);
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, -0.1, -2.5);
  root.add(backdrop);
  disposables.geometries.push(backdropGeo);
  disposables.materials.push(backdropMat);

  // ---- radial contact shadow (grounded element) ----
  const shadowGeo = new PlaneGeometry(3.4, 3.4);
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const shadowUv = uv().sub(vec2(0.5, 0.5));
  const shadowDist = length(shadowUv);
  shadowMat.colorNode = color('#000000');
  shadowMat.opacityNode = smoothstep(0.5, 0.0, shadowDist).mul(0.5);
  const contactShadow = new Mesh(shadowGeo, shadowMat);
  contactShadow.rotation.x = -Math.PI / 2;
  contactShadow.position.set(0, -1.35, 0.2);
  root.add(contactShadow);
  disposables.geometries.push(shadowGeo);
  disposables.materials.push(shadowMat);

  // ---- lighting: rig-dusk-editorial (color.ink/color.paper/color.accent not used here, neutral rig) ----
  const ambient = new AmbientLight(0xffffff, 0.09);
  root.add(ambient);

  const key = new DirectionalLight(0xffc890, 2.8);
  key.position.set(3, 0.9, 1.2);
  const keyTarget = new Object3D();
  keyTarget.position.set(0, 0.4, 0);
  root.add(keyTarget);
  key.target = keyTarget;
  root.add(key);

  const fill = new PointLight(0xb9a68e, 3, 9, 2);
  fill.position.set(-2.4, 0.6, 1.8);
  root.add(fill);

  const rim = new DirectionalLight(0xf2f4f6, 1.7);
  rim.position.set(-1.8, 2.8, -2);
  const rimTarget = new Object3D();
  rimTarget.position.set(0, 0.6, 0);
  root.add(rimTarget);
  rim.target = rimTarget;
  root.add(rim);

  // ---- filmstrip group : effects.spec composition ----
  const filmstrip = new Group();
  filmstrip.name = 'filmstrip';
  filmstrip.rotation.y = THREE.MathUtils.degToRad(-18);
  root.add(filmstrip);

  const CARD_W = 1.6;
  const CARD_H = 1.0;
  const PITCH = 1.85;
  const FOCUS_INDEX = 2; // center card of 5

  const cardGeo = new PlaneGeometry(CARD_W, CARD_H);
  const frameGeo = new BoxGeometry(CARD_W + 0.05, CARD_H + 0.05, 0.025);
  const underlineGeo = new PlaneGeometry(1.6, 0.035);
  disposables.geometries.push(cardGeo, frameGeo, underlineGeo);

  const neutralTints = ['#ffffff', '#e8ecf2', '#c7ccd6', '#9aa0ab', '#6b6f78'];
  const cardGroups = [];

  for (let j = 0; j < 5; j++) {
    const offset = j - FOCUS_INDEX;
    const isFocused = j === FOCUS_INDEX;

    const cardGroup = new Group();
    cardGroup.position.x = offset * PITCH;

    // machined ink bevel frame (color.ink)
    const frameMat = new MeshStandardNodeMaterial({
      color: PALETTE.ink,
      roughness: 0.6,
      metalness: 0.3,
    });
    const frame = new Mesh(frameGeo, frameMat);
    frame.position.z = -0.02;
    cardGroup.add(frame);
    disposables.materials.push(frameMat);

    // card plate material — roughness .55 metalness .2 clearcoat .15
    const cardMat = new MeshPhysicalNodeMaterial({
      roughness: 0.55,
      metalness: 0.2,
      clearcoat: 0.15,
      transparent: true,
      color: neutralTints[j],
    });
    const card = new Mesh(cardGeo, cardMat);
    cardGroup.add(card);
    disposables.materials.push(cardMat);

    // counter-rotate / scale per focus rule
    if (isFocused) {
      cardGroup.rotation.y = THREE.MathUtils.degToRad(18); // cancel strip rotation -> face camera
      cardGroup.scale.setScalar(1.0);
      card.material.opacity = 1.0;
    } else {
      cardGroup.rotation.y = 0;
      cardGroup.scale.setScalar(0.92);
      const dist = Math.abs(offset);
      const maxDist = 2;
      card.material.opacity = THREE.MathUtils.clamp(1.0 - (dist / maxDist) * 0.45, 0.55, 1.0);
    }

    // caption text under each card
    const captionItem = captionItems[j];
    if (captionItem) {
      const captionText = ctx.fontAtlas.createText(captionItem.text, {
        fontSize: 18,
        color: PALETTE.paper,
        align: 'center',
        letterSpacingPx: 1.5,
      });
      captionText.position.set(0, -0.65, 0.02);
      cardGroup.add(captionText);
    }

    // focused card gets accent underline bar, emissive 1.3
    if (isFocused) {
      const underlineMat = new MeshStandardNodeMaterial({
        color: PALETTE.accent,
        emissive: PALETTE.accent,
        emissiveIntensity: 1.3,
        roughness: 0.4,
        metalness: 0.1,
      });
      const underline = new Mesh(underlineGeo, underlineMat);
      underline.position.set(0, -0.54, 0.02);
      cardGroup.add(underline);
      disposables.materials.push(underlineMat);
    }

    filmstrip.add(cardGroup);
    cardGroups.push({ group: cardGroup, mesh: card, isFocused });
  }

  // load the single provided photograph and apply to all card materials
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    disposables.textures.push(tex);
    for (const { mesh } of cardGroups) {
      mesh.material.map = tex;
      mesh.material.needsUpdate = true;
    }
  });

  // ---- headline / body pinned in world space (not affected by strip rotation) ----
  if (headlineItem) {
    const headline = ctx.fontAtlas.createText(headlineItem.text, {
      fontSize: 68,
      color: PALETTE.paper,
      align: 'left',
    });
    headline.position.set(-2.6, 1.5, 0);
    root.add(headline);
  }

  if (bodyItem) {
    const body = ctx.fontAtlas.createText(bodyItem.text, {
      fontSize: 26,
      color: PALETTE.paper,
      align: 'left',
    });
    body.position.set(-2.6, -1.5, 0);
    root.add(body);
  }

  // ---- primitive.parallax-scroll ----
  const primitiveSpecs = config.cinematicPrimitives ?? [];
  for (const prim of primitiveSpecs) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const target = prim.name === 'parallax-scroll' ? filmstrip : root;
      const handle = fn(target, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- entrance motion: weighted-settle ----
  root.position.y = -0.4;
  root.scale.setScalar(0.985);
  const entranceTl = gsap.timeline();
  entranceTl.to(root.position, { y: 0, duration: 0.7, ease: 'power3.out' });
  entranceTl.to(
    root.scale,
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power2.out' },
    0.1
  );
  entranceTl.to(
    root.scale,
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    0.55
  );
  timelines.push(entranceTl);

  // ---- idle motion: single slow breathing transform (<=2%) ----
  const idleTl = gsap.timeline({ repeat: -1, yoyo: true });
  idleTl.to(root.scale, {
    x: 1.015,
    y: 1.015,
    z: 1.015,
    duration: 4.5,
    ease: 'sine.inOut',
  });
  timelines.push(idleTl);

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    for (const tl of timelines) tl.kill();
    for (const handle of primitiveHandles) {
      if (handle && typeof handle.cleanup === 'function') handle.cleanup();
    }
    for (const g of disposables.geometries) g.dispose?.();
    for (const m of disposables.materials) m.dispose?.();
    for (const t of disposables.textures) t.dispose?.();
    root.traverse((obj) => {
      if (obj.geometry && !disposables.geometries.includes(obj.geometry)) {
        obj.geometry.dispose?.();
      }
      if (obj.material && !disposables.materials.includes(obj.material)) {
        obj.material.dispose?.();
      }
    });
  };

  return root;
}

/* @spec-manifest
{"elements":[
  {"id":"text.headline.0","where":"createNode:headline block","how":"ctx.fontAtlas.createText headlineItem at [-2.6,1.5,0]"},
  {"id":"text.body.1","where":"createNode:body block","how":"ctx.fontAtlas.createText bodyItem at [-2.6,-1.5,0]"},
  {"id":"text.caption.2","where":"createNode:card loop captionItems[0]","how":"caption text child of card group j=0"},
  {"id":"text.caption.3","where":"createNode:card loop captionItems[1]","how":"caption text child of card group j=1"},
  {"id":"text.caption.4","where":"createNode:card loop captionItems[2]","how":"caption text child of focused card group j=2"},
  {"id":"text.caption.5","where":"createNode:card loop captionItems[3]","how":"caption text child of card group j=3"},
  {"id":"text.caption.6","where":"createNode:card loop captionItems[4]","how":"caption text child of card group j=4"},
  {"id":"color.background","where":"backdropMat.colorNode","how":"gradient stop #0b0b10 mixed via uv.y"},
  {"id":"color.surface","where":"PALETTE.surface constant","how":"defined for palette discipline reference"},
  {"id":"color.ink","where":"frameMat","how":"MeshStandardNodeMaterial color #16161d bevel frame"},
  {"id":"color.paper","where":"headline/body/caption text color","how":"ctx.fontAtlas color #e8ecf2"},
  {"id":"color.accent","where":"underlineMat","how":"emissive #ff2a38 underline bar intensity 1.3"},
  {"id":"color.gradient","where":"backdropMat.colorNode","how":"mix(#0b0b10,#12121a,uv.y) 2-stop gradient"},
  {"id":"effects.spec","where":"filmstrip group + cardGroups loop","how":"5 cards 1.6x1.0 @1.85 pitch, -18deg strip, focus counter-rotate"},
  {"id":"primitive.parallax-scroll","where":"primitiveSpecs loop","how":"ctx.primitives['parallax-scroll'](filmstrip,{intensity:0.5})"}
]}
*/
